module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       Cout
);

    // Bit 0 sum has no carry-in.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_bit1_sum_from_carry0: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 sum uses the carry from adding the lower two bits.
    check_bit2_sum_from_lower_bits: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]})[2]))
    );

    // Bit 3 sum uses the carry from adding the lower three bits.
    check_bit3_sum_from_lower_bits: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]})[3]))
    );

    // Carry-out matches the MSB of the extended addition.
    check_cout_from_extended_add: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B})[4])
    );

    // Full adder result matches 4-bit unsigned addition.
    check_full_result_from_add: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B})
    );

endmodule